const $=s=>document.querySelector(s),fmt=n=>Number.isSafeInteger(n)?new Intl.NumberFormat('pt-BR').format(n):'Em apuração',month=p=>new Date(p+'-02T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'});let records=[],activities=[];
function el(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;}
function chart(target,key,color){const root=$(target);root.replaceChildren();const year=$('#impact-year').value;const points=records.filter(r=>r.periodo.startsWith(year)&&Number.isSafeInteger(r[key])).sort((a,b)=>a.periodo.localeCompare(b.periodo));if(!points.length){root.append(el('p','Os gráficos serão exibidos quando houver resultados confirmados publicados.'));return;}const max=Math.max(1,...points.map(r=>r[key]));for(const r of points){const row=el('div');row.className='impact-bar-row';const label=el('span',new Date(r.periodo+'-02T12:00:00').toLocaleDateString('pt-BR',{month:'short'})),track=el('div');track.className='impact-bar-track';const bar=el('span');bar.className='impact-bar';bar.style.width=(100*r[key]/max)+'%';bar.style.background=color;track.append(bar);row.append(label,track,el('strong',fmt(r[key])));row.setAttribute('aria-label',month(r.periodo)+': '+fmt(r[key]));root.append(row);}}
function render(){const r=records.find(r=>r.periodo===$('#impact-period').value);for(const key of ['cadastros','pessoas','familias','atendimentos','cestas','voluntarios','acoes'])$('[data-metric="'+key+'"]').textContent=r?fmt(r[key]):'Em apuração';$('#impact-status').textContent=r?.manual?'Resultados publicados · '+month(r.periodo):'Cadastros e ações atualizados · demais resultados aguardam publicação';$('#impact-updated').textContent=r?.manual?'Atualizado em '+new Date(r.atualizado_em).toLocaleDateString('pt-BR'):'Cadastros e ações são atualizados a cada consulta desta página.';$('#impact-partners').replaceChildren();if(r?.parceiros?.length){for(const name of r.parceiros){const card=el('div');card.className='impact-partner';card.append(el('span','PARCERIA CONFIRMADA'),el('strong',name));$('#impact-partners').append(card);}}else $('#impact-partners').append(el('p',r?'Nenhuma parceria foi informada nesta publicação.':'As parcerias serão exibidas após confirmação e autorização para divulgação.'));chart('#visits-chart','atendimentos','linear-gradient(90deg,#0b75bc,#7151bb)');chart('#food-chart','cestas','linear-gradient(90deg,#047e82,#d09b28)');renderActions();}
async function start(){try{const previous=$('#impact-period').value;const response=await fetch('/api/impacto');if(!response.ok)throw Error('Não foi possível carregar os resultados.');const data=await response.json();const ar=await fetch('/api/acoes');if(!ar.ok)throw Error();activities=(await ar.json()).items;const periods=new Set([new Date(Date.now()-3*60*60*1000).toISOString().slice(0,7),...data.periodos.map(r=>r.periodo),...data.cadastros.map(r=>r.periodo),...data.acoes.map(r=>r.periodo)]);records=[...periods].sort().reverse().map(periodo=>{const manual=data.periodos.find(r=>r.periodo===periodo);return{...manual,periodo,manual:!!manual&&manual.publicada!==false,cadastros:data.cadastros.find(r=>r.periodo===periodo)?.total||0,acoes:data.acoes.find(r=>r.periodo===periodo)?.total||0};});$('#impact-period').replaceChildren();$('#impact-year').replaceChildren();for(const r of records){const o=el('option',month(r.periodo));o.value=r.periodo;$('#impact-period').append(o);}for(const year of [...new Set(records.map(r=>r.periodo.slice(0,4)))]){const o=el('option',year);o.value=year;$('#impact-year').append(o);}if(records.length){$('#impact-period option[value=""]')?.remove();$('#impact-year option[value=""]')?.remove();}const requested=new URLSearchParams(location.search).get('periodo')||previous;const selected=records.find(r=>r.periodo===requested)||records.find(r=>r.manual)||records[0];if(selected){$('#impact-period').value=selected.periodo;$('#impact-year').value=selected.periodo.slice(0,4);}render();}catch(e){$('#impact-status').textContent='Resultados temporariamente indisponíveis. Tente novamente mais tarde.';}}
$('#impact-period').onchange=()=>{const period=$('#impact-period').value;if(period)$('#impact-year').value=period.slice(0,4);render();};$('#impact-year').onchange=render;start();

function renderActions(){const root=$('#public-actions');root.replaceChildren();const selected=$('#impact-period').value,items=activities.filter(a=>a.data_realizacao.startsWith(selected));if(!items.length){root.append(el('p','As ações realizadas aparecerão aqui após a publicação pela equipe do Instituto.'));return;}for(const action of items){const card=el('article');card.className='public-action';const date=el('time',new Date(action.data_realizacao+'T12:00:00').toLocaleDateString('pt-BR'));date.dateTime=action.data_realizacao;card.append(date,el('h3',action.titulo),el('p',action.resumo));if(action.conteudo){const detail=el('details');detail.append(el('summary','Ler relato completo'),el('p',action.conteudo));card.append(detail);}root.append(card);}}

window.addEventListener('focus',start);setInterval(()=>{if(!document.hidden)start();},60000);
